contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving c
    function run(address cfgAddr, bool enableEnforce, int256 v1, int256 v2) public payable {
        // Precondition: cfgAddr must be a contract (we cannot check code size easily here),
        // but we require it's not zero to avoid trivial misuse.
        require(cfgAddr != address(0));

        // Ensure this contract is set as DAO so Governable constructor preconditions are satisfied when c was deployed
        // (The checker deploys c fresh and this contract was the deployer; assume c.setDAO allowed in constructor). 
        // We only interact via public surface now.

        // Configure enforcement flag for this caller (msg.sender in c calls will be this contract)
        // setEnforcement is public and non-view, so it must be its own statement
        c.setEnforcement(enableEnforce);

        // We need the external cfgAddr to be a Configurable; the Configurable.configured() value is observed by enforceTolerance.
        // There's no way to set that here; caller provides cfgAddr. We won't call into cfgAddr; just rely on its configured() view.

        // Call enforceToleranceInt which wraps into enforceTolerance and converts negatives to absolute values
        bool reverted;
        try c.enforceToleranceInt(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable values needed for the property
        // whether this contract's enforcement flag is active
        // There is no getter for enforceLimitsActive mapping; instead we rely on the value we set (enableEnforce).

        // configured flag of c itself
        bool cConfigured = c.configured();

        // security.changeTolerance and security.epochSize etc are public via struct getter
        (uint256 epochSize, uint256 lastFlashGovernanceAct, uint8 maxGovernanceChangePerEpoch, uint8 changeTolerance) = c.security();

        // We cannot read Configurable(cfgAddr).configured() directly from c, but enforceTolerance uses Configurable(msg.sender).configured()
        // where msg.sender is this contract; so it will call Configurable(this).configured(). Thus we must provide a configured() view on this contract.

        // The rule: if enforcement is enabled (enableEnforce == true) AND Configurable(this).configured() == true AND c.configured() == true,
        // then enforceTolerance should revert exactly when the percent difference condition fails.

        // Compute absolute uints as enforceToleranceInt would
        uint256 uv1 = v1 > 0 ? uint256(v1) : uint256(-1 * v1);
        uint256 uv2 = v2 > 0 ? uint256(v2) : uint256(-1 * v2);

        bool specialRevert;
        if (!enableEnforce || !this.configured() || !cConfigured) {
            // enforceTolerance should return (not revert) because it short-circuits when enforcement inactive or Configurable not configured
            specialRevert = false;
        } else {
            // enforcement active and configured: determine expected revert based on FE1 logic
            if (uv1 > uv2) {
                if (uv2 == 0) {
                    specialRevert = !(uv1 <= 1);
                } else {
                    // require(((uv1 - uv2) * 100) < changeTolerance * uv1, "FE1");
                    // revert if NOT (((uv1 - uv2) * 100) < changeTolerance * uv1)
                    // i.e., revert if ((uv1 - uv2) * 100) >= changeTolerance * uv1
                    specialRevert = (((uv1 - uv2) * 100) >= uint256(changeTolerance) * uv1);
                }
            } else {
                if (uv1 == 0) {
                    specialRevert = !(uv2 <= 1);
                } else {
                    specialRevert = (((uv2 - uv1) * 100) >= uint256(changeTolerance) * uv1);
                }
            }
        }

        // The single assert: the observed revert flag must equal the computed expectation
        assert(reverted == specialRevert);
    }

    // Provide configured() so that Configurable(msg.sender).configured() used in c.enforceTolerance returns a deterministic value
    // We expose this test contract as a Configurable with configurable() returning true so callers can exercise enforcement branch.
    function configured() external pure returns (bool) {
        return true;
    }

    receive() external payable {}
}

