contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry: take parameters that will be forwarded to configureFlashGovernance
    function run(address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // record previous config
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = (c.flashGovernanceConfig().amount, c.flashGovernanceConfig().unlockTime, c.flashGovernanceConfig().asset, c.flashGovernanceConfig().assetBurnable);

        bool reverted;
        // call that may revert; must be a top-level statement
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = (c.flashGovernanceConfig().amount, c.flashGovernanceConfig().unlockTime, c.flashGovernanceConfig().asset, c.flashGovernanceConfig().assetBurnable);

        // If call reverted, config must be unchanged; if not reverted, config must equal inputs
        assert(reverted ? (
            after_amount == before_amount &&
            after_unlockTime == before_unlockTime &&
            after_asset == before_asset &&
            after_assetBurnable == before_assetBurnable
        ) : (
            after_amount == amount &&
            after_unlockTime == unlockTime &&
            after_asset == asset &&
            after_assetBurnable == assetBurnable
        ));
    }

    receive() external payable {}
}

