contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for the property-based test
    function run(int256 v1, int256 v2) public payable {
        // read configured flag from c (public getter exists named configured)
        bool cfg = c.configured();

        // call enforceToleranceInt and record whether it reverted
        bool revertedInt;
        try c.enforceToleranceInt(v1, v2) {
            revertedInt = false;
        } catch {
            revertedInt = true;
        }

        // compute absolute values as uint256 in the same way C does
        uint256 uv1 = uint256(v1 > 0 ? v1 : -1 * v1);
        uint256 uv2 = uint256(v2 > 0 ? v2 : -1 * v2);

        // call enforceTolerance on the unsigned values and record whether it reverted
        bool revertedUint;
        try c.enforceTolerance(uv1, uv2) {
            revertedUint = false;
        } catch {
            revertedUint = true;
        }

        // The rule:
        // - if contract is not configured, enforceToleranceInt should never revert
        // - otherwise, enforceToleranceInt reverts iff enforceTolerance on absolute values reverts
        assert((!cfg && revertedInt == false) || (cfg && revertedInt == revertedUint));
    }

    receive() external payable {}
}

