contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entrypoint
    function run(address targetContract, address asset) public payable {
        // No preconditions on inputs
        // Read current pending info for this contract (msg.sender for c calls will be this test contract)
        // Note: public mapping getter pendingFlashDecision returns (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable) in struct order
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        // attempt withdraw; it may revert according to contract rules
        try c.withdrawGovernanceAsset{value: 0}(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-state
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

