contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We will attempt to call withdrawGovernanceAsset for a given target and asset.
    // Preconditions: none on c (freshly deployed by checker). We take parameters that
    // identify the target contract and asset addresses and an address presumed to be msg.sender
    // in the context of the pending decision: since the checker runs run() once and
    // msg.sender for calls to c will be this contract, we assert properties about behavior
    // when this contract calls withdrawGovernanceAsset.
    function run(address targetContract, address asset) public payable {
        require(true);

        // Read current pending config for (targetContract, this contract) via the public getter.
        // The getter is: pendingFlashDecision(address,address) returns (FlashGovernanceConfig)
        // auto-generated getter returns the tuple: (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable)
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // Record c balance and this balance before call
        uint256 balanceC_before = address(c).balance;
        uint256 balanceThis_before = address(this).balance;

        bool reverted;
        // attempt the withdraw; it may revert if preconditions (asset match, amount>0, unlockTime < now) are not met
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read pending entry after the call
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));
        uint256 balanceC_after = address(c).balance;
        uint256 balanceThis_after = address(this).balance;

        // General rule to assert:
        // If the withdraw succeeded (not reverted) then:
        //   - before_amount > 0
        //   - before_asset == asset
        //   - before_unlockTime < block.timestamp
        //   - this contract received exactly before_amount tokens in ether value terms cannot be observed,
        //     but the contract transfers ERC20 tokens, not Ether. However we can observe that the pending entry was cleared
        //     (after_amount == 0 and after_asset == address(0)). Since we cannot observe ERC20 balance inside this test,
        //     we assert that the pending entry was deleted and that the call did not change c's Ether balance.
        // If the withdraw reverted then at least one of the required preconditions was false.

        // We capture that assertion as a single boolean formula below.
        assert(
            // Case A: call reverted => one of the preconditions must have failed
            (
                reverted && (
                    // either asset mismatch
                    !(before_asset == asset && before_amount > 0 && before_unlockTime < block.timestamp)
                )
            )
            ||
            // Case B: call succeeded => pending entry cleared and no Ether moved from c to this
            (
                !reverted &&
                // pending entry was cleared: amount==0 and asset reset (getter returns 0 address when deleted)
                after_amount == 0 && after_asset == address(0) &&
                // c's Ether balance unchanged by this call (withdrawGovernanceAsset transfers ERC20 tokens, not Ether)
                balanceC_after == balanceC_before &&
                // this contract's Ether balance unchanged as well
                balanceThis_after == balanceThis_before &&
                // and the before entry matched the requested asset and had positive amount and was unlocked
                before_asset == asset && before_amount > 0 && before_unlockTime < block.timestamp
            )
        );
    }

    receive() external payable {}
}

