contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to withdraw a pending flash governance asset and assert that
    // when the call succeeds, the stored pending amount for (targetContract, msg.sender)
    // becomes zero (observable through the public getter flashGovernanceConfig/pendingFlashDecision mapping fields).
    // Because pendingFlashDecision is a public mapping of structs, Solidity auto-generates a getter
    // with the same name. The getter signature is:
    // function pendingFlashDecision(address, address) public view returns (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable);

    // Note: msg.sender for calls into c will be this contract. The test takes as inputs
    // a targetContract address and an asset address. It will first read the pending
    // entry for (targetContract, address(this)) before calling withdrawGovernanceAsset.

    function run(address targetContract, address asset) public payable {
        require(true);

        // Read the pending decision before attempting withdraw
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        // Attempt withdrawGovernanceAsset. The function is external and may revert if preconditions fail.
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the pending decision after the call
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // General rule: if withdrawGovernanceAsset did NOT revert, then after the call the pending amount must be zero
        // (i.e. the pendingFlashDecision entry was deleted), and the asset/address/amount fields must reflect deletion.
        // We express deletion as after_amount == 0.
        assert(reverted || after_amount == 0);
    }

    receive() external payable {}
}

